class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def greet(self):
        return f'Hello, my name is {self.name}'

# Creating objects
person1 = Person('Alice', 30)
person2 = Person('Bob', 25)

print(person1.greet())  # Hello, my name is Alice

class Car:
    def __init__(self, make, model):
        self.make = make
        self.model = model
        self.speed = 0

    def accelerate(self):
        self.speed += 10

    def brake(self):
        self.speed = max(0, self.speed - 10)

    def get_speed(self):
        return self.speed

my_car = Car('Toyota', 'Camry')
my_car.accelerate()
print(my_car.get_speed())  # 10
